#!/usr/bin/env python3
"""Kode v0.2: adds the tests, docs, examples and small text files.

Run it from the root of your Kode repository (the folder that holds Cargo.toml), AFTER
copying the Rust files (the crates/ folder and Cargo.toml) over your project:

    python3 kode-v0.2-add-files.py

It writes 106 files and removes 5 obsolete ones. It never touches anything else.
"""
import os
import sys

